"""CI pipeline generator abstraction."""

import abc
import os

import yaml

HEADER = (
    "# Generated by envforge from {manifest}. Do not edit by hand;\n"
    "# change envforge.yaml and run 'envforge ci generate' instead.\n"
)


class _Dumper(yaml.SafeDumper):
    """SafeDumper that indents lists under their keys (matches CI-config style)."""

    def increase_indent(self, flow=False, indentless=False):
        return super().increase_indent(flow, False)


def _str_presenter(dumper, data):
    if "\n" in data:
        return dumper.represent_scalar("tag:yaml.org,2002:str", data, style="|")
    return dumper.represent_scalar("tag:yaml.org,2002:str", data)


_Dumper.add_representer(str, _str_presenter)


def dump_yaml(data):
    return yaml.dump(data, Dumper=_Dumper, sort_keys=False, default_flow_style=False, width=100)


class CIGenerator(abc.ABC):
    name = "abstract"
    default_path = ""

    def __init__(self, manifest):
        self.manifest = manifest
        ci = manifest.ci or {}
        self.python_versions = [str(v) for v in ci.get("python_versions") or [manifest.python]]
        self.os_list = [str(v) for v in ci.get("os") or ["ubuntu-latest"]]
        self.install = str(ci.get("install") or "pip install env-forge")
        self.branches = [str(b) for b in ci.get("branches") or ["main"]]
        self.affected_only = bool(ci.get("affected_only", False))

    @property
    def components(self):
        return sorted(self.manifest.components)

    def uses_docker(self):
        return any(self.manifest.provisioner_for(c) == "docker"
                   for c in self.manifest.components.values())

    def header(self):
        rel = os.path.basename(self.manifest.path or "envforge.yaml")
        return HEADER.format(manifest=rel)

    @abc.abstractmethod
    def build(self):
        """Return the pipeline as a plain dict."""

    def render(self):
        return self.header() + dump_yaml(self.build())

    def output_path(self):
        return os.path.join(self.manifest.root, self.default_path)
